CREATE TABLE [dbo].[ccgenTelMarcados](	  [telefono] VARCHAR(19) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [fecha] SMALLDATETIME NOT NULL	, [cal_key] VARCHAR(40) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [cam_id] INT NOT NULL	, [cantidad] INT NOT NULL	, [semana] SMALLINT NOT NULL	, CONSTRAINT [PK_ccgenTelMarcados] PRIMARY KEY ([telefono] ASC, [fecha] ASC, [cal_key] ASC, [cam_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccgenTelMarcados] ON [dbo].[ccgenTelMarcados] ([cam_id] ASC)